interface FileInputProps {
  accept?: string; // e.g. 'image/png, image/jpeg, application/pdf
  maxSizeInMB?: number;
  onFileChange?: (files: FileList) => void | Promise<void>;
  allowMultiple?: boolean;
}

const FileInput = ({
  accept = 'image/png, image/jpeg, application/pdf',
  maxSizeInMB = 10,
  onFileChange,
  allowMultiple = false
}: FileInputProps) => {
  const [state, setState] = useState<'idle' | 'loading' | 'success'>('idle');
  const [error, setError] = useState<string | null>(null);
  const [files, setFiles] = useState<FileList | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const pending = useRef(false);

  const handleFileInputClick = () => {
    fileInputRef.current?.click();
  };

  const processFiles = async (files: FileList | null) => {
    if (pending.current || !files?.length) return;
    setError(null);
    if (!allowMultiple && files.length > 1) {
      setError('Choose only one file.');
      return;
    }

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const { success, message } = validateFile(file, accept, maxSizeInMB);
      if (!success) {
        setError(message || 'Something went wrong.');
        return;
      }
    }

    pending.current = true;
    setState('loading');
    try {
      await onFileChange?.(files);
    } catch (error) {
      console.error(error);
      setState('idle');
      setError('Something went wrong.');
      return;
    } finally {
      pending.current = false;
    }
    setFiles(files);
    setState('success');
  };

  const onChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    void processFiles(event.target.files);
    event.target.value = '';
  };

  const handleDrop = (event: React.DragEvent) => {
    void processFiles(event.dataTransfer.files);
  };

  const handleRemove = () => {
    setFiles(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
    setState('idle');
  };

  return (
    <div className="w-[300px] h-[200px] relative overflow-hidden">
      <input
        type="file"
        hidden
        ref={fileInputRef}
        className="hidden"
        accept={accept}
        onChange={onChange}
        multiple={allowMultiple}
      />
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.div
          key={state}
          className="h-full w-full overflow-hidden rounded-xl"
          initial={{
            y: state === 'loading' ? '-100%' : '100%',
            filter: 'blur(10px)',
            scale: 1,
            borderRadius: '100%'
          }}
          animate={{ y: 0, filter: 'blur(0px)', scale: 1, borderRadius: '0%' }}
          exit={{
            y: ['loading', 'success'].includes(state) ? '-100%' : '100%',
            filter: 'blur(10px)',
            scale: 0.7,
            borderRadius: '100%'
          }}
          transition={{
            type: 'spring',
            duration: 0.4,
            bounce: 0
          }}
        >
          {state === 'idle' && (
            <Idle
              accept={accept}
              maxSizeInMB={maxSizeInMB}
              onClick={handleFileInputClick}
              onDrop={handleDrop}
              error={error}
            />
          )}
          {state === 'loading' && <Loading />}
          {state === 'success' && files && <Success files={files} onRemove={handleRemove} />}
        </motion.div>
      </AnimatePresence>
    </div>
  );
};

export default FileInput;

